-- CFB Wheel of Football runtime integration.
-- Adds the locked 68-school current CFB scope to the existing NFL Wheel architecture.
-- CFB uses the same private pick snapshots, 2.5x final-grade calibration, exact-total
-- winner resolution, and match-wide player/coach uniqueness as NFL.

alter table private.wheel_football_teams
  alter column division drop not null;

alter table private.wheel_football_teams
  drop constraint if exists wheel_football_teams_conference_check;

alter table private.wheel_football_teams
  add constraint wheel_football_teams_conference_check
  check (conference in ('AFC', 'NFC', 'SEC', 'Big Ten', 'Big 12', 'ACC', 'Independent'));

alter table private.wheel_football_teams
  drop constraint if exists wheel_football_teams_division_check;

alter table private.wheel_football_teams
  add constraint wheel_football_teams_division_check
  check (
    (conference in ('AFC', 'NFC') and division in ('East', 'North', 'South', 'West'))
    or (conference in ('SEC', 'Big Ten', 'Big 12', 'ACC', 'Independent') and division is null)
  );

