create or replace function private.create_wheel_football_challenge(
  p_recipient_id uuid,
  p_pool_scope text,
  p_division text
)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_creator_id uuid := auth.uid();
  v_creator_name text;
  v_scope text := upper(trim(coalesce(p_pool_scope, '')));
  v_division text;
  v_code text;
  v_attempt integer := 0;
  v_challenge_id uuid;
  v_created_at timestamptz;
  v_summary text;
  v_is_cfb boolean;
begin
  if v_creator_id is null then
    raise exception 'sign in required';
  end if;

  if p_recipient_id is null or p_recipient_id = v_creator_id then
    raise exception 'choose another profile';
  end if;

  if not exists (select 1 from public.profiles where id = p_recipient_id) then
    raise exception 'profile not found';
  end if;

  if v_scope not in ('NFL', 'AFC', 'NFC', 'DIVISION', 'CFB', 'SEC', 'BIG_TEN', 'BIG_12', 'ACC') then
    raise exception 'invalid Wheel of Football pool';
  end if;

  v_is_cfb := v_scope in ('CFB', 'SEC', 'BIG_TEN', 'BIG_12', 'ACC');

  if v_scope = 'DIVISION' then
    v_division := case upper(trim(coalesce(p_division, '')))
      when 'AFC EAST' then 'AFC East'
      when 'AFC NORTH' then 'AFC North'
      when 'AFC SOUTH' then 'AFC South'
      when 'AFC WEST' then 'AFC West'
      when 'NFC EAST' then 'NFC East'
      when 'NFC NORTH' then 'NFC North'
      when 'NFC SOUTH' then 'NFC South'
      when 'NFC WEST' then 'NFC West'
      else null
    end;
    if v_division is null then
      raise exception 'choose an NFL division';
    end if;
  else
    v_division := null;
  end if;

  select profile.display_name
    into v_creator_name
  from public.profiles profile
  where profile.id = v_creator_id;

  v_summary := case
    when v_is_cfb then 'Current CFB · ' || case v_scope
      when 'CFB' then 'National'
      when 'BIG_TEN' then 'Big Ten'
      when 'BIG_12' then 'Big 12'
      else v_scope
    end
    else 'Current NFL · ' || case
      when v_scope = 'NFL' then 'Full NFL'
      when v_scope = 'DIVISION' then v_division
      else v_scope
    end
  end;

  loop
    v_attempt := v_attempt + 1;
    v_code := upper(substr(replace(extensions.gen_random_uuid()::text, '-', ''), 1, 8));
    begin
      insert into public.play_challenges (
        code,
        game_id,
        game_version,
        game_title,
        summary,
        creator_id,
        recipient_id,
        play_url,
        setup,
        creator_result
      ) values (
        v_code,
        'wheel-football',
        'football-wheel-v2',
        'Wheel of Football',
        v_summary,
        v_creator_id,
        p_recipient_id,
        '/football/wheel?match=' || v_code,
        jsonb_build_object(
          'league', case when v_is_cfb then 'CFB' else 'NFL' end,
          'poolScope', v_scope,
          'division', v_division,
          'currentOnly', true,
          'rosterSlots', jsonb_build_array('QB', 'RB', 'WR', 'Flex', 'Front Seven', 'Secondary', 'Head Coach')
        ),
        jsonb_build_object('status', 'in-progress')
      )
      returning id, created_at into v_challenge_id, v_created_at;
      exit;
    exception when unique_violation then
      if v_attempt >= 5 then raise; end if;
    end;
  end loop;

  insert into private.wheel_football_matches (
    challenge_id,
    pool_scope,
    division
  ) values (
    v_challenge_id,
    v_scope,
    v_division
  );

  perform private.publish_notification_to_profile(
    p_recipient_id,
    'wheel-football:received:' || v_code || ':' || p_recipient_id::text,
    'play-challenges:received',
    'game_challenge_received',
    'You were challenged',
    v_creator_name || ' challenged you to Wheel of Football.',
    '/football/wheel?match=' || v_code,
    'PLAY',
    v_created_at
  );

  return v_code;
end;
$$;

create or replace function private.spin_wheel_football(p_code text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
  v_challenge public.play_challenges%rowtype;
  v_match private.wheel_football_matches%rowtype;
  v_last_team text;
  v_team_code text;
begin
  if v_user_id is null then
    raise exception 'sign in required';
  end if;

  select challenge.*
    into v_challenge
  from public.play_challenges challenge
  where challenge.code = upper(trim(p_code))
    and challenge.game_id = 'wheel-football'
    and (challenge.creator_id = v_user_id or challenge.recipient_id = v_user_id);

  if not found then
    raise exception 'Wheel of Football match not found';
  end if;

  select match.*
    into v_match
  from private.wheel_football_matches match
  where match.challenge_id = v_challenge.id
  for update;

  if v_challenge.declined_at is not null or v_challenge.completed_at is not null then
    raise exception 'This Wheel of Football match is closed';
  end if;

  if v_challenge.opened_at is null then
    raise exception 'The challenge must be accepted before the first spin';
  end if;

  if v_match.current_turn_profile_id <> v_user_id or v_match.phase <> 'spin' then
    raise exception 'It is not your spin';
  end if;

  v_last_team := case
    when v_user_id = v_challenge.creator_id then v_match.creator_last_team_code
    else v_match.recipient_last_team_code
  end;

  select team.code
    into v_team_code
  from private.wheel_football_teams team
  where (
      (v_match.pool_scope = 'NFL' and team.conference in ('AFC', 'NFC'))
      or (v_match.pool_scope in ('AFC', 'NFC') and team.conference = v_match.pool_scope)
      or (
        v_match.pool_scope = 'DIVISION'
        and team.conference || ' ' || team.division = v_match.division
      )
      or (
        v_match.pool_scope = 'CFB'
        and team.conference in ('SEC', 'Big Ten', 'Big 12', 'ACC', 'Independent')
      )
      or (v_match.pool_scope = 'SEC' and team.conference = 'SEC')
      or (v_match.pool_scope = 'BIG_TEN' and team.conference = 'Big Ten')
      or (v_match.pool_scope = 'BIG_12' and team.conference = 'Big 12')
      or (v_match.pool_scope = 'ACC' and team.conference = 'ACC')
    )
    and (v_last_team is null or team.code <> v_last_team)
  order by random()
  limit 1;

  if v_team_code is null then
    raise exception 'No team is available for this wheel';
  end if;

  update private.wheel_football_matches match
  set phase = 'pick',
      pending_team_code = v_team_code,
      updated_at = now()
  where match.challenge_id = v_challenge.id;

  return private.wheel_football_state_json(v_challenge.id);
end;
$$;

create or replace function private.enrich_completed_wheel_football_result()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_forfeited_at timestamptz;
  v_creator_raw numeric;
  v_recipient_raw numeric;
  v_creator_final numeric;
  v_recipient_final numeric;
begin
  if new.game_id <> 'wheel-football' or new.completed_at is null then
    return new;
  end if;

  if coalesce(new.creator_result ? 'finalGrade', false)
    and coalesce(new.responder_result ? 'finalGrade', false) then
    return new;
  end if;

  select match.forfeited_at
    into v_forfeited_at
  from private.wheel_football_matches match
  where match.challenge_id = new.id;

  if v_forfeited_at is not null then
    return new;
  end if;

  v_creator_raw := private.wheel_football_raw_grade(new.id, new.creator_id);
  v_recipient_raw := private.wheel_football_raw_grade(new.id, new.recipient_id);

  if v_creator_raw is null or v_recipient_raw is null then
    return new;
  end if;

  v_creator_final := private.wheel_football_final_grade_v2(v_creator_raw);
  v_recipient_final := private.wheel_football_final_grade_v2(v_recipient_raw);

  update public.play_challenges challenge
  set creator_result = coalesce(challenge.creator_result, '{}'::jsonb) || jsonb_build_object(
        'finalGrade', v_creator_final,
        'wheelGradeRuntimeVersion', 'wheel-football-locked-grades-v3'
      ),
      responder_result = coalesce(challenge.responder_result, '{}'::jsonb) || jsonb_build_object(
        'finalGrade', v_recipient_final,
        'wheelGradeRuntimeVersion', 'wheel-football-locked-grades-v3'
      )
  where challenge.id = new.id;

  return new;
end;
$$;

revoke all on function private.create_wheel_football_challenge(uuid,text,text) from public, anon;
revoke all on function private.spin_wheel_football(text) from public, anon;
revoke all on function private.enrich_completed_wheel_football_result() from public, anon, authenticated;

grant execute on function private.create_wheel_football_challenge(uuid,text,text) to authenticated;
grant execute on function private.spin_wheel_football(text) to authenticated;

comment on table private.wheel_football_grade_authority is
  'Private NFL + CFB Wheel grading authority. Individual grades are never exposed to clients.';
comment on function private.create_wheel_football_challenge(uuid,text,text) is
  'Creates a current NFL or 68-school current CFB Wheel challenge using reviewed pool scopes.';
comment on function private.spin_wheel_football(text) is
  'Selects one random eligible NFL team or CFB school from the match pool while blocking only the actor''s immediately previous spin.';
comment on function private.pick_wheel_football(text,text,text,text,text,text,text) is
  'Locks one eligible current NFL/CFB player or head coach into an open Superteam slot; any identity already drafted by either participant is unavailable.';
comment on function private.enrich_completed_wheel_football_result() is
  'Writes only the final calibrated Superteam grade after natural completion; individual frozen pick grades remain private.';
